+//! Graph-owned construction and validation of durable release intents.
+//!
+//! This module intentionally accepts an already-resolved [`ReleaseSelection`].
+//! Version and publish planning are separate commands with their own policy and
+//! diagnostics; calling either here would make validation execute planning and
+//! turn a received intent into a new authorization decision.  Construction and
+//! validation instead use the same read-only workspace projection.
+
+use std::collections::{BTreeMap, BTreeSet};
+use std::path::Path;
+
+use callisto_model::{
+    CanonicalTranscript, CommandRunner, Ecosystem, ExecutionTrustProfileV1, PublishTarget, ReleaseInputComponentV1,
+    ReleaseInputSnapshotV1, ReleaseIntentV1, ReleaseOperation, ReleaseOperationId, ReleasePackageId,
+    SemanticInputDigest, SourceIdentity, Version,
+};
