+/// Exact package/version values selected by a preceding, user-visible release
+/// decision.  It is deliberately data, not a planner trait: validation must
+/// never call `plan_publish` or `plan_version` to reinterpret an approval.
+#[derive(Clone, Debug, Default, PartialEq, Eq)]
+pub struct ReleaseSelection {
+    versions: BTreeMap<ReleasePackageId, Version>,
+}
+
+impl ReleaseSelection {
+    pub fn new(versions: BTreeMap<ReleasePackageId, Version>) -> Self {
+        Self { versions }
+    }
+
+    pub fn versions(&self) -> &BTreeMap<ReleasePackageId, Version> {
+        &self.versions
+    }
+}
+
+/// A graph-issued, in-memory capability proving one [`ReleaseIntentV1`] was
+/// rebuilt against this workspace.  It has private fields and deliberately
+/// implements neither `Clone` nor serialization.
+pub struct ValidatedReleaseIntent {
+    intent: ReleaseIntentV1,
+}
+
+impl ValidatedReleaseIntent {
+    /// Returns the validated durable intent for read-only inspection.
+    pub fn intent(&self) -> &ReleaseIntentV1 {
+        &self.intent
+    }
+}
+
+/// Builds a canonical release intent from one workspace and an explicit
+/// selection. This never invokes either version or publish planning.
+pub fn build_release_intent<R: CommandRunner, D: DependencyResolver>(
+    ws: &Workspace<'_, R, D>,
+    selection: &ReleaseSelection,
+    source: SourceIdentity,
+    trust_profile: ExecutionTrustProfileV1,
+) -> Result<ReleaseIntentV1, GraphError> {
+    let (snapshot, operations) = derive_release_inputs(ws, selection, source)?;
+    ReleaseIntentV1::new(snapshot, trust_profile, operations)
+        .map_err(|error| GraphError::ReleaseIntentStale)
+}
+
+/// Rebuilds the exact snapshot and operation DAG from `ws`. Equality is the
+/// authorization check: any stale manifest/config/source/selection input is
+/// rejected before callers can receive the opaque capability.
+pub fn validate_release_intent<R: CommandRunner, D: DependencyResolver>(
+    ws: &Workspace<'_, R, D>,
+    selection: &ReleaseSelection,
+    received: ReleaseIntentV1,
+) -> Result<ValidatedReleaseIntent, GraphError> {
+    let expected = build_release_intent(ws, selection, received.snapshot.source.clone(), received.trust_profile)?;
+    if expected != received {
+        return Err(GraphError::ReleaseIntentStale);
+    }
+    Ok(ValidatedReleaseIntent { intent: received })
+}
+
+fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
+    ws: &Workspace<'_, R, D>,
+    selection: &ReleaseSelection,
+    source: SourceIdentity,
+) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
+    let mut components = Vec::new();
+    let mut seen = BTreeSet::new();
+    let mut selected_packages = BTreeMap::new();
+
+    for package in ws.graph.packages() {
+        for ecosystem in package
+            .canonical_manifests()
+            .map(|manifest| manifest.ecosystem())
+            .collect::<BTreeSet<_>>()
+        {
+            let release_id = ReleasePackageId::new(ecosystem, package.id.name())
+                .map_err(|_| GraphError::ReleasePackageNotSelected {
+                    package: ReleasePackageId::new(ecosystem, package.id.name()).expect("existing package identity"),
+                })?;
+            if let Some(version) = selection.versions().get(&release_id) {
+                selected_packages.insert(release_id, (package, version.clone()));
+            }
+        }
+    }
+    for selected in selection.versions().keys() {
+        if !selected_packages.contains_key(selected) {
+            return Err(GraphError::ReleasePackageNotSelected {
+                package: selected.clone(),
+            });
+        }
+    }
+
+    // Policy components are semantic inputs even when they do not create an
+    // operation for this selection. Only their digest is durable.
+    push_component(
+        &mut components,
+        &mut seen,
+        "policy.cascade",
+        format!("{:?}", ws.config.cascade),
+    );
+    push_component(
+        &mut components,
+        &mut seen,
+        "policy.validation",
+        format!("{:?}", ws.config.validation),
+    );
+    push_component(&mut components, &mut seen, "policy.groups", format!("{:?}", ws.config.groups));
+
+    for (key, registry) in &ws.config.registries {
+        let binding = match &registry.url {
+            Some(url) => normalize_registry_url(key.as_str(), url)?,
+            None => "default".to_string(),
+        };
+        push_component(
+            &mut components,
+            &mut seen,
+            format!("registry-binding:{}", key.as_str()),
+            format!("{}:{}", registry.kind.prefix(), binding),
+        );
+    }
+
+    let mut operations_by_id = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
+    for (release_id, (package, version)) in &selected_packages {
+        let mut package_input = format!("id={release_id};version={}", version.render());
+        for manifest in &package.manifests {
+            let bytes = std::fs::read(ws.root.join(&manifest.path)).map_err(|error| GraphError::ReleaseInputRead {
+                path: manifest.path.clone(),
+                message: error.to_string(),
+            })?;
+            package_input.push_str(&format!(
+                ";manifest={}:{}:{:?}:{:?}",
+                manifest.path.display(),
+                digest_bytes("manifest", &bytes),
+                manifest.role,
+                manifest.format
+            ));
+        }
+        package_input.push_str(&format!(";trigger={:?};tag={}", package.release_trigger, package.tag_template.as_ref().map_or_else(|| "default".to_string(), |tag| tag.as_str())));
+
+        let mut publish_ids = Vec::new();
+        let mut has_release_target = false;
+        let mut forge_release = false;
+        for target in &package.publish_to {
+            match target {
+                PublishTarget::None => {}
+                PublishTarget::GitHubRelease => {
+                    has_release_target = true;
+                    forge_release = true;
+                    package_input.push_str(";target=github-release");
+                }
+                _ => {
+                    has_release_target = true;
+                    package_input.push_str(&target_fingerprint(target)?);
+                    if target.ecosystem() == Some(release_id.ecosystem()) {
+                        if let Some(key) = target.registry_key() {
+                            let operation = ReleaseOperation::registry_publish(
+                                release_id.clone(),
+                                version.clone(),
+                                key.as_str().to_string(),
+                                Vec::new(),
+                            )
+                            .map_err(|_| GraphError::ReleaseIntentStale)?;
+                            publish_ids.push(operation.id().clone());
+                            operations_by_id.insert(operation.id().clone(), operation);
+                        }
+                    }
+                }
+            }
+        }
+        push_component(&mut components, &mut seen, format!("package:{release_id}"), package_input);
+
+        if has_release_target {
+            publish_ids.sort();
+            let tag = ReleaseOperation::tag(release_id.clone(), version.clone(), publish_ids)
+                .map_err(|_| GraphError::ReleaseIntentStale)?;
+            let tag_id = tag.id().clone();
+            operations_by_id.insert(tag_id.clone(), tag);
+            if forge_release {
+                let release = ReleaseOperation::forge_release(release_id.clone(), version.clone(), vec![tag_id])
+                    .map_err(|_| GraphError::ReleaseIntentStale)?;
+                operations_by_id.insert(release.id().clone(), release);
+            }
+        }
+    }
+
+    let snapshot = ReleaseInputSnapshotV1::new(source, components);
+    Ok((snapshot, operations_by_id.into_values().collect()))
+}
+
+fn push_component(components: &mut Vec<ReleaseInputComponentV1>, seen: &mut BTreeSet<String>, kind: impl Into<String>, value: String) {
+    let kind = kind.into();
+    debug_assert!(seen.insert(kind.clone()), "release snapshot component kinds must be unique");
+    components.push(ReleaseInputComponentV1 {
+        kind,
+        fingerprint: digest_text("component", &value),
+    });
+}
+
+fn digest_text(tag: &str, text: &str) -> SemanticInputDigest {
+    let mut transcript = CanonicalTranscript::semantic_input_v1();
+    transcript.push_str(tag, text);
+    SemanticInputDigest::from_transcript(&transcript)
+}
+
+fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
+    let mut transcript = CanonicalTranscript::semantic_input_v1();
+    transcript.push_bytes(tag, bytes);
+    SemanticInputDigest::from_transcript(&transcript)
+}
+
+fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
+    match target {
+        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
+        PublishTarget::Npm { registry, access } => Ok(format!(
+            ";target=npm:{}:{access:?}",
+            registry
+                .as_deref()
+                .map(|url| normalize_registry_url("npm", url))
+                .transpose()?
+                .unwrap_or_else(|| "default".to_string())
+        )),
+        PublishTarget::Pypi { index } => Ok(format!(
+            ";target=pypi:{}",
+            index
+                .as_deref()
+                .map(|url| normalize_registry_url("pypi", url))
+                .transpose()?
+                .unwrap_or_else(|| "default".to_string())
+        )),
+        PublishTarget::NuGet { source } => Ok(format!(
+            ";target=nuget:{}",
+            source
+                .as_deref()
+                .map(|url| normalize_registry_url("nuget", url))
+                .transpose()?
+                .unwrap_or_else(|| "default".to_string())
+        )),
+        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
+        PublishTarget::None => Ok(";target=none".to_string()),
+        #[allow(unreachable_patterns)]
+        _ => Ok(";target=future".to_string()),
+    }
+}
+
+/// Produces the credential-free binding form used only as digest input.
+fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
+    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
+        registry: registry.to_string(),
+        reason: "missing scheme",
+    })?;
+    if scheme.is_empty() || remainder.is_empty() {
+        return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "empty scheme or authority" });
+    }
+    if remainder.contains('@') {
+        return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "userinfo is forbidden" });
+    }
+    if remainder.contains('?') {
+        return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "query string is forbidden" });
+    }
+    if remainder.contains('#') {
+        return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "fragment is forbidden" });
+    }
+    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
+    if authority.is_empty() || authority.contains(char::is_whitespace) {
+        return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "invalid authority" });
+    }
+    Ok(format!("{}://{}{}", scheme.to_ascii_lowercase(), authority.to_ascii_lowercase(), if path.is_empty() { "" } else { &format!("/{path}") }))
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn registry_binding_rejects_credential_bearing_or_ambiguous_urls() {
+        for value in [
+            "https://token@registry.example.test/index",
+            "https://registry.example.test/index?token=secret",
+            "https://registry.example.test/index#fragment",
+        ] {
+            assert!(normalize_registry_url("test", value).is_err(), "{value} must be rejected");
+        }
+        assert_eq!(
+            normalize_registry_url("test", "HTTPS://Registry.Example.Test:443/index").unwrap(),
+            "https://registry.example.test:443/index"
+        );
+    }
+
+    #[test]
+    fn selection_is_data_not_a_planner_seam() {
+        let id = ReleasePackageId::new(Ecosystem::Cargo, "example").unwrap();
+        let version = Version::parse("1.2.3", callisto_model::VersionGrammar::SemVer).unwrap();
+        let selection = ReleaseSelection::new(BTreeMap::from([(id.clone(), version.clone())]));
+        assert_eq!(selection.versions().get(&id), Some(&version));
+    }
+}
